const path = require('path');
const { greet } = require('./utils');
const { loadConfig } = require('./config');

// Resolved against this module, not process.cwd(): package.json points `main`
// here, so the app must start the same way from any working directory.
const CONFIG_PATH = path.join(__dirname, '..', 'app.conf');

function main() {
  let config;
  try {
    config = loadConfig(CONFIG_PATH);
  } catch (err) {
    console.error(`Could not read config file ${CONFIG_PATH}: ${err.message}`);
    process.exit(1);
  }

  // Fail loudly at startup rather than letting a missing key reach output as
  // the string "undefined".
  if (config.name === undefined) {
    console.error(`Missing required key "name" in ${CONFIG_PATH}`);
    process.exit(1);
  }

  console.log(greet(config.name));
}

main();

